Voici un extrait de <code>authService</code>. Quelle fonction est manquante pour gérer le rafraîchissement du token ?

<pre style='background:#2d2d2d; color:#f8f8f2; padding:8px; border-radius:4px;'>
export const authService = {
  login: (data: LoginRequest) => api.post('/auth/login', data),
  register: (data: RegisterRequest) => api.post('/auth/register', data),
  sendOtp: (phone: string) => api.post('/auth/send-otp', { phone }),
  verifyOtp: (data: OtpRequest) => api.post('/auth/verify-otp', data),
  // Fonction manquante
  getProfile: () => api.get('/users/me'),
  updateProfile: (data: UpdateProfileRequest) => api.put('/users/me', data),
};
</pre>

Voici un extrait du service <code>productService</code>. Quelle est la bonne implémentation pour la fonction de mise à jour d'un produit avec upload d'images ?

<pre style='background:#2d2d2d; color:#f8f8f2; padding:8px; border-radius:4px;'>
// Version A
updateProduct: (id: string, data: any) => 
  api.put(`/products/${id}`, data)

// Version B
updateProduct: (id: string, data: any) => 
  api.put(`/products/${id}`, data, { 
    headers: { 'Content-Type': 'multipart/form-data' } 
  })

// Version C
updateProduct: (id: string, data: FormData) => 
  api.put(`/products/${id}`, data)

// Version D
updateProduct: (id: string, data: FormData) => 
  api.put(`/products/${id}`, data, { 
    headers: { 'Content-Type': 'application/json' } 
  })
</pre>
